/* Pick one filing that actually worked, from a pool of recent ones.
 *
 * WHY A POOL. The workflow used to read /api/trades/congress/latest — one
 * filing, the newest. Filtering that to winners does not work: roughly half of
 * filings are losers, and when the newest one is a loser there is nothing else
 * to fall back to, so the account goes dark until a new filing happens to land
 * green. Reading a window of recent filings and choosing within it keeps the
 * cadence while only ever publishing a trade that worked.
 *
 * WHAT "WORKED" MEANS. transactions.performance already answers "did this go the
 * filer's way?" for both directions — server/updatePerformance.ts computes
 *     buy  → (current - tx) / tx        positive = the stock rose after buying
 *     sell → (tx - current) / tx        positive = the stock FELL after selling
 * so a single `performance > 0` test is the right filter for buys and sales
 * alike. This is also the exact column the website renders per trade
 * (strategy-detail.tsx calculatePerformance, politician-profile.tsx
 * getTransactionPerformance), so it is passed through to the card unchanged —
 * a post showing -22% for a trade the site's own table shows as +22% reads as a
 * bug to anyone who clicks through.
 *
 * BEATING THE INDEX IS PART OF IT. A buy up 4% while the S&P rose 12% is not a
 * good trade, and a card showing a green badge above a longer gold bar argues
 * against itself. Both thresholds have to clear.
 */

// ── Tune these ────────────────────────────────────────────────────────────
const MIN_FILER_RESULT_PCT = 5;     // the trade must have gone their way by this much
const MIN_EDGE_VS_INDEX_PCT = 2;    // ...and beaten the S&P over the same window
const MAX_FILING_AGE_DAYS = 90;     // ...and still be recent enough to be news
const MAX_ENTRY_DRIFT_DAYS = 10;    // how stale an S&P entry bar may be vs the trade date
const MIN_HOURS_BETWEEN_POSTS = 20; // at most one post a day, whichever run wins
// ──────────────────────────────────────────────────────────────────────────

const staticData = $getWorkflowStaticData('global');

/* Cadence guard — check this before doing any work.
 *
 * The trigger fires every 15 minutes. That used to be self-limiting: the
 * workflow read one filing, the newest, and lastTradeId blocked re-posting until
 * a genuinely new filing arrived. Selecting from a pool removes that limit —
 * dozens of filings can qualify at once, so without this the account would post
 * a different winner every 15 minutes until the pool ran dry.
 *
 * Polling every 15 minutes and gating here (rather than moving the trigger to
 * once a day) means a failed or empty run simply retries on the next tick
 * instead of costing the whole day. */
const lastPostedAt = staticData.lastPostedAt ? new Date(staticData.lastPostedAt) : null;
const hoursSinceLastPost = lastPostedAt ? (Date.now() - lastPostedAt.getTime()) / 3600000 : null;
if (hoursSinceLastPost !== null && hoursSinceLastPost < MIN_HOURS_BETWEEN_POSTS) {
  console.log(
    `Posted ${hoursSinceLastPost.toFixed(1)}h ago; waiting for ${MIN_HOURS_BETWEEN_POSTS}h. No post.`,
  );
  return [{
    json: {
      isNew: false,
      skipReason: 'posted_too_recently',
      hoursSinceLastPost: Number(hoursSinceLastPost.toFixed(2)),
      nextEligibleInHours: Number((MIN_HOURS_BETWEEN_POSTS - hoursSinceLastPost).toFixed(2)),
    },
  }];
}

/* Every fetch node runs with fullResponse + neverError, so each produces exactly
 * one item shaped { body, statusCode, headers }. Two reasons that matters:
 *
 *   1. An array body stays whole in `.body` instead of being split into N items,
 *      which is what stops a 300-row response from firing the next request 300
 *      times. `executeOnce` used to do that job and lost the data doing it.
 *   2. A failed request arrives as a status code rather than as an empty list.
 *      Those two are indistinguishable otherwise, and telling them apart is the
 *      difference between "no trade qualified" and "the API is down". */
function responseOf(nodeName) {
  let items;
  try {
    items = $(nodeName).all();
  } catch (e) {
    return { ok: false, status: null, body: null, why: `node "${nodeName}" did not run` };
  }
  const first = items && items[0] ? items[0].json : null;
  if (!first) return { ok: false, status: null, body: null, why: 'no output' };

  // An n8n-level failure (timeout, DNS, connection refused) yields an item with
  // `error` and no statusCode, rather than an HTTP envelope.
  if (first.error !== undefined && first.body === undefined) {
    const msg = typeof first.error === 'string' ? first.error : JSON.stringify(first.error);
    return { ok: false, status: null, body: null, why: `request failed: ${String(msg).slice(0, 160)}` };
  }

  const status = Number(first.statusCode);
  const hasStatus = Number.isFinite(status);
  const body = first.body !== undefined ? first.body : first;
  const ok = hasStatus ? status >= 200 && status < 300 : true;
  return { ok, status: hasStatus ? status : null, body, why: ok ? null : `HTTP ${status}` };
}

const filingsRes = responseOf('Get Recent Congress Filings');
const barsRes = responseOf('Get S&P 500 History');
const polRes = responseOf('Get Politicians');

const filings = (Array.isArray(filingsRes.body) ? filingsRes.body : [])
  .filter(r => r && r.id && r.stockTicker);

const bars = (Array.isArray(barsRes.body) ? barsRes.body : [])
  .filter(b => b && b.date && Number.isFinite(Number(b.close)))
  .map(b => ({ date: String(b.date).slice(0, 10), close: Number(b.close) }))
  .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

const politicians = Array.isArray(polRes.body) ? polRes.body : [];
const politicianById = new Map(politicians.map(p => [String(p.id), p]));

/* Fail on the SOURCE before scoring anything.
 *
 * Without this, an empty benchmark response is reported as 300 individually
 * unbenchmarkable trades — which reads like "nothing qualified today" when the
 * truth is "the S&P feed returned nothing". That misdiagnosis is exactly what
 * this block exists to prevent, and it names the HTTP status so the next step is
 * obvious. */
function sourceFailure(label, res, rows, minRows) {
  if (!res.ok) return `${label} unavailable (${res.why})`;
  if (rows.length < minRows) {
    return `${label} returned ${rows.length} usable row(s), need at least ${minRows}`
      + (res.status ? ` — HTTP ${res.status}, so the endpoint answered but had no data` : '');
  }
  return null;
}

// Two bars is the minimum for a return: an entry and a later exit.
const sourceProblem =
  sourceFailure('congress filings', filingsRes, filings, 1) ||
  sourceFailure('S&P 500 history', barsRes, bars, 2) ||
  // An empty politician table rejects every candidate for a missing name, which
  // would otherwise be reported as "nothing qualified" — the same misdiagnosis
  // this block exists to prevent.
  sourceFailure('politician lookup', polRes, politicians, 1);

if (sourceProblem) {
  console.error(`Aborting: ${sourceProblem}. This is a data-source problem, not "nothing qualified".`);
  return [{
    json: {
      isNew: false,
      skipReason: 'source_unavailable',
      sourceProblem,
      diagnostics: {
        filings: { status: filingsRes.status, rows: filings.length, why: filingsRes.why },
        sp500: { status: barsRes.status, bars: bars.length, why: barsRes.why },
        politicians: { status: polRes.status, rows: politicians.length, why: polRes.why },
      },
    },
  }];
}

// A partial table is survivable: those candidates are skipped rather than posting
// a card with a blank NAME row. A fully empty one was caught above.

// ── Duplicate suppression ────────────────────────────────────────────────
// Filtering to winners shrinks the pool, which makes repetition MORE likely,
// so this is now load-bearing rather than a nicety. The Instagram response is
// treated as untrustworthy: if it is not the shape we expect we fall back to
// our own record and say so, instead of silently letting duplicates through.
const igRes = responseOf('Get Last 10 Instagram Posts');
const igBody = igRes.body && typeof igRes.body === 'object' ? igRes.body : {};
const igOk = igRes.ok && Array.isArray(igBody.data);
const recentCaptions = igOk ? igBody.data.slice(0, 10).map(p => String(p.caption ?? '')) : [];
if (!igOk) {
  // Non-fatal, unlike the sources above: we still hold our own record of what we
  // published. But it is reported, because an expired token looks exactly like a
  // quiet feed and stayed unnoticed for six days once already.
  const detail = igRes.why || (igBody.error && igBody.error.message) || 'unexpected response shape';
  console.warn(
    `Instagram feed unreadable (${detail}) — falling back to the local published-ticker `
    + 'record only. Duplicate suppression is degraded this run.',
  );
}

const publishedTickers = new Set(
  (Array.isArray(staticData.recentPublishedTickers) ? staticData.recentPublishedTickers : [])
    .map(t => String(t).trim().toUpperCase())
    .filter(Boolean),
);
const publishedIds = new Set(
  (Array.isArray(staticData.publishedTradeIds) ? staticData.publishedTradeIds : []).map(String),
);

// Match the exact cashtag or hashtag, so ticker T does not match TSLA.
function inRecentCaptions(ticker) {
  if (!ticker || !recentCaptions.length) return false;
  const escaped = ticker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = new RegExp(`(?:\\$|#)${escaped}(?![A-Z0-9.])`, 'i');
  return recentCaptions.some(c => pattern.test(c));
}

// ── Helpers ──────────────────────────────────────────────────────────────
const DAY = 86400000;
const today = new Date().toISOString().slice(0, 10);
const lastBar = bars.length ? bars[bars.length - 1] : null;

function benchmarkSince(tradeDate) {
  if (!lastBar || !tradeDate) return null;
  const first = bars.find(b => b.date >= tradeDate);
  if (!first || first.close <= 0) return null;
  // The entry bar must be near the trade date. If the S&P history starts later
  // than the trade, the index gets scored over a shorter window than the stock,
  // which quietly flatters the trade.
  if (Math.round((new Date(first.date) - new Date(tradeDate)) / DAY) > MAX_ENTRY_DRIFT_DAYS) return null;
  if (lastBar.date <= first.date) return null;
  return ((lastBar.close - first.close) / first.close) * 100;
}

// The API hands back the raw disclosure string; the range parsing used to live
// in /api/trades/congress/latest, which this no longer calls.
function parseAmountRange(raw) {
  const s = String(raw ?? '');
  const clean = v => parseInt(v.replace(/[$,]/g, ''), 10);
  const range = s.match(/\$[\d,]+\s*-\s*\$[\d,]+/);
  if (range) {
    const parts = range[0].split('-').map(x => x.trim());
    return { min: clean(parts[0]), max: clean(parts[1]) };
  }
  const single = s.match(/>\s*\$[\d,]+/);
  if (single) return { min: clean(single[0].replace('>', '').trim()), max: null };
  return { min: null, max: null };
}

// The DB stores parties in French; the feed is in English.
function party(raw) {
  const s = String(raw ?? '');
  if (/d[ée]mocrat/i.test(s)) return 'Democrat';
  if (/r[ée]publicain|republican/i.test(s)) return 'Republican';
  return s || null;
}

const numeric = v => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));

// ── Score every candidate ────────────────────────────────────────────────
const rejected = { no_performance: 0, no_benchmark: 0, below_result_floor: 0, lost_to_index: 0,
                   too_old: 0, duplicate: 0, no_politician: 0 };
const eligible = [];

for (const r of filings) {
  const ticker = String(r.stockTicker).trim().toUpperCase();
  const tradeDate = r.date ? String(r.date).slice(0, 10) : null;
  const filedDate = r.reportDate ? String(r.reportDate).slice(0, 10) : tradeDate;
  const isBuy = /purchase|buy|achat/i.test(String(r.action ?? ''));

  if (!numeric(r.performance) || !numeric(r.transactionPrice) || !numeric(r.currentPrice)) {
    rejected.no_performance++;
    continue;
  }
  const filerResult = Number(r.performance);

  const ageDays = filedDate ? Math.round((new Date(today) - new Date(filedDate)) / DAY) : null;
  if (ageDays === null || ageDays > MAX_FILING_AGE_DAYS) { rejected.too_old++; continue; }

  // Covers both a trade that went against them and one that went their way by
  // too little to be worth a post.
  if (filerResult < MIN_FILER_RESULT_PCT) { rejected.below_result_floor++; continue; }

  const benchmark = benchmarkSince(tradeDate);
  if (!numeric(benchmark)) { rejected.no_benchmark++; continue; }

  // Edge vs the index. For a buy this is the site's own alpha construction
  // (strategy-detail.tsx: performance - sp500Return). For a sale the two add:
  // they escaped a fall of `filerResult` while the index rose `benchmark`.
  const edge = isBuy ? filerResult - benchmark : filerResult + benchmark;
  if (edge < MIN_EDGE_VS_INDEX_PCT) { rejected.lost_to_index++; continue; }

  if (publishedIds.has(String(r.id)) || publishedTickers.has(ticker) || inRecentCaptions(ticker)) {
    rejected.duplicate++;
    continue;
  }

  const p = r.politicianId ? politicianById.get(String(r.politicianId)) : null;
  if (!p || !p.name) { rejected.no_politician++; continue; }
  const { min, max } = parseAmountRange(r.amount);

  eligible.push({
    id: r.id,
    ticker,
    politician: p.name,
    party: party(p.party),
    type: r.action,
    is_buy: isBuy,
    amount_min: min,
    amount_max: max,
    trade_date: tradeDate,
    filed_date: filedDate,
    // Same value the website shows for this trade. Positive = it went their way,
    // for buys and sales alike.
    performance_pct: Number(filerResult.toFixed(2)),
    benchmark_pct: Number(benchmark.toFixed(2)),
    benchmark_label: 'S&P 500',
    filer_edge_pct: Number(edge.toFixed(2)),
    lag_days: tradeDate && filedDate ? Math.round((new Date(filedDate) - new Date(tradeDate)) / DAY) : null,
    filing_age_days: ageDays,
  });
}

// Freshest first, biggest edge as the tie-break. Ranking by edge alone would
// park the account on one monster trade and re-post it as soon as it aged out
// of the duplicate window.
eligible.sort((a, b) =>
  a.filed_date === b.filed_date
    ? b.filer_edge_pct - a.filer_edge_pct
    : (a.filed_date < b.filed_date ? 1 : -1),
);

const pick = eligible[0] || null;

if (!pick) {
  const summary = Object.entries(rejected).filter(([, v]) => v > 0).map(([k, v]) => `${k}=${v}`).join(' ');
  console.log(
    `Nothing qualifies from ${filings.length} filings (${summary || 'pool empty'}). ` +
    'No post — silence beats manufacturing a story.',
  );
  return [{
    json: {
      isNew: false,
      skipReason: 'no_qualifying_trade',
      candidatesConsidered: filings.length,
      rejected,
      instagramFeedReadable: igOk,
      diagnostics: { sp500Bars: bars.length, politicians: politicians.length },
    },
  }];
}

console.log(
  `Selected ${pick.ticker} (${pick.is_buy ? 'buy' : 'sale'}) — performance +${pick.performance_pct}%, ` +
  `edge +${pick.filer_edge_pct}% vs S&P, filed ${pick.filing_age_days}d ago. ` +
  `${eligible.length} of ${filings.length} filings qualified.`,
);

return [{
  json: {
    ...pick,
    isNew: true,
    skipReason: null,
    candidatesConsidered: filings.length,
    qualified: eligible.length,
    rejected,
    instagramFeedReadable: igOk,
  },
}];

// The transaction was marked as seen before the branch.
// Keep this pass-through node so existing workflow connections remain stable.
return [{ json: $json }];

// Merge Claude tagline with original trade data
const claudeResp = $input.first().json;
const trade      = $('Select Best Winner').first().json;
const rawTagline = claudeResp?.content?.[0]?.text?.trim() || 'Trade like an insider.';
// Strip surrounding quotes if Claude added them
const tagline = rawTagline.replace(/^["']|["']$/g, '').trim();
return [{ json: { ...trade, tagline } }];

// Build the Instagram caption and carry imageUrl forward.
const imageData = $input.first().json;
const trade = $('Merge Tagline').first().json;

function fmt(n) {
  return n >= 1e6 ? `$${(n / 1e6).toFixed(1)}M` : `$${Math.round(n / 1e3)}K`;
}
function amount(min, max) {
  if (!min && !max) return 'Undisclosed';
  if (!max) return `${fmt(min)}+`;
  return `${fmt(min)} – ${fmt(max)}`;
}
function pct(n) {
  const v = Number(n);
  return `${v >= 0 ? '+' : ''}${v.toFixed(1)}%`;
}

const ticker = trade.ticker || '';
const isBuy = trade.is_buy === true;
// The same figure the site shows for this trade: positive = it went their way.
const perf = Number(trade.performance_pct);
const bench = Number(trade.benchmark_pct);
const lag = trade.lag_days;

const headline = isBuy
  ? `$${ticker} is ${pct(perf)} since the buy`
  : `$${ticker} fell ${Math.abs(perf).toFixed(1)}% after the sale`;

// The one sentence that must survive any edit to this template. `performance` is
// measured from the disclosed transaction price — it is the filer's window, not a
// follower's, because the filing only became public weeks later. Drop it and a
// data post becomes a performance claim the number does not support.
// This sentence must survive any edit. The figure is measured from the disclosed
// transaction price, so it is the filer's window, not a follower's.
const basis = isBuy
  ? `Measured from the price at the disclosed transaction to the latest price we hold. That is the filer's result, not a follower's${lag !== null ? ` — the filing became public ${lag} days after the trade` : ''}.`
  : `Measured from the price at the disclosed sale to the latest price we hold — the fall they got out ahead of${lag !== null ? `, disclosed ${lag} days after the sale` : ''}.`;

// filer_edge_pct is signed for the direction of the trade: for a sale the
// advantage is the index rising while the stock fell, so it is bench − move,
// not move − bench. Printing the raw difference showed a good sale as negative.
const edge = Number(trade.filer_edge_pct);
const versus = isBuy
  ? `${ticker} ${pct(perf)} vs ${trade.benchmark_label || 'S&P 500'} ${pct(bench)} over the same window — ${pct(edge)} ahead of the index.`
  : `${ticker} fell ${Math.abs(perf).toFixed(1)}% while the ${trade.benchmark_label || 'S&P 500'} rose ${pct(bench)} — ${pct(edge)} avoided by getting out.`;

const caption = [
  `${isBuy ? '🟢' : '🔴'} ${headline}`,
  ``,
  `${trade.politician}${trade.party ? ` (${trade.party})` : ''} disclosed a ${isBuy ? 'purchase' : 'sale'} of $${ticker} worth ${amount(trade.amount_min, trade.amount_max)}.`,
  ``,
  `📊 ${versus}`,
  `📅 Traded: ${trade.trade_date || 'Unknown'}`,
  `📋 Disclosed: ${trade.filed_date || 'Unknown'}`,
  ``,
  basis,
  ``,
  trade.tagline,
  ``,
  `Every Congress filing, tracked and benchmarked: insideroption.com`,
  ``,
  `#CongressTrades #StockMarket #${ticker} #Investing #InsiderOption #SP500 #StockAct #WallStreet`,
].join('\n');

return [{ json: { ...trade, imageUrl: imageData.imageUrl, caption } }];

const container = $input.first().json;
const trade     = $('Build Caption').first().json;
return [{ json: { ...trade, containerId: container.id } }];

const staticData = $getWorkflowStaticData('global');
const trade = $('Save Container ID').first().json;
const ticker = String(trade.ticker ?? '').trim().toUpperCase();

const recentPublishedTickers = Array.isArray(staticData.recentPublishedTickers)
  ? staticData.recentPublishedTickers
      .map(value => String(value).trim().toUpperCase())
      .filter(Boolean)
      .slice(-9)
  : [];

if (ticker) {
  recentPublishedTickers.push(ticker);
}

staticData.recentPublishedTickers = recentPublishedTickers.slice(-10);

// Also remember the exact trade ids. Selecting the best winner from a pool means
// the same standout filing stays eligible for as long as it is inside the
// freshness window, so a ticker-only memory would re-post it once it fell out of
// the last-10 captions.
const publishedTradeIds = (Array.isArray(staticData.publishedTradeIds) ? staticData.publishedTradeIds : [])
  .map(String)
  .filter(Boolean);
if (trade.id) publishedTradeIds.push(String(trade.id));
staticData.publishedTradeIds = publishedTradeIds.slice(-200);

// Stamped here, at the end of the chain, rather than at selection: if the image
// service or the Instagram publish fails, the next 15-minute tick should be free
// to retry instead of the day's slot being spent on a post that never landed.
staticData.lastPostedAt = new Date().toISOString();

return [{
  json: {
    success: true,
    postedTradeId: trade.id,
    ticker,
    politician: trade.politician,
    trade_date: trade.trade_date,
    igPostId: $input.first().json.id,
    postedAt: new Date().toISOString(),
    recentPublishedTickers: staticData.recentPublishedTickers,
    lastPostedAt: staticData.lastPostedAt,
  },
}];
